-- Загружаем все предметы из items.json
for json.decode(io.contents("data/items.json")).data as item do
    if item.gameRef ~= ""
        and not item_name_to_type[item.i18n.en.name]
    then
        item_name_to_type[item.i18n.en.name] = item.gameRef
    end
end

-- Вручную добавляем моды Ривен (если нужно переопределить)
item_name_to_type["Rifle Riven Mod (Veiled)"] = "/Lotus/Upgrades/Mods/Randomized/RawRifleRandomMod"
item_name_to_type["Shotgun Riven Mod (Veiled)"] = "/Lotus/Upgrades/Mods/Randomized/RawShotgunRandomMod"
