item_name_to_type["Zaw Riven Mod (Veiled)"] = "/Lotus/Upgrades/Mods/Randomized/RawModularMeleeRandomMod"
item_name_to_type["Kitgun Riven Mod (Veiled)"] = "/Lotus/Upgrades/Mods/Randomized/RawModularPistolRandomMod"
item_name_to_type["Sentinel Weapon Riven Mod (Veiled)"] = "/Lotus/Upgrades/Mods/Randomized/RawSentinelWeaponRandomMod"

-- ============================================
-- Функция для автоматической генерации цен
-- ============================================
local function generate_prices()
    local default_price = { buy = 10, sell = 5 } -- Цена по умолчанию
    
    local price_rules = {
        -- Высокие цены
        { pattern = "/Lotus/Upgrades/Mods/Randomized/", buy = 50, sell = 25 },  -- Ривен моды
        { pattern = "/Lotus/Powersuits/", buy = 30, sell = 15 },                -- Варфреймы
        { pattern = "/Lotus/Weapons/Tenno/", buy = 25, sell = 12 },             -- Оружие
        { pattern = "/Lotus/Upgrades/CosmeticEnhancers/", buy = 40, sell = 20 },-- Арканы
        { pattern = "/Lotus/Types/Recipes/WarframeRecipes/", buy = 15, sell = 7 },-- Чертежи варфреймов
        
        -- Средние цены
        { pattern = "/Lotus/Types/Recipes/", buy = 10, sell = 5 },              -- Чертежи
        { pattern = "/Lotus/Types/Items/FusionTreasures/", buy = 5, sell = 2 }, -- Аятаны
        { pattern = "/Lotus/Types/Items/MiscItems/", buy = 3, sell = 1 },       -- Ресурсы
        
        -- Низкие цены
        { pattern = "/Lotus/Types/Keys/", buy = 2, sell = 1 },                  -- Ключи
        { pattern = "/Lotus/Types/Items/Emotes/", buy = 1, sell = 0.5 },        -- Эмодзи
    }
    
    local prices = {}
    for name, gameRef in pairs(item_name_to_type) do
        local buy_price = default_price.buy
        local sell_price = default_price.sell
        for _, rule in ipairs(price_rules) do
            if string.find(gameRef, rule.pattern) then
                buy_price = rule.buy
                sell_price = rule.sell
                break
            end
        end
        prices[name] = { buy_price, sell_price }
    end
    return prices
end

-- Генерируем цены
local generated_prices = generate_prices()

-- Возвращаем обе таблицы
return item_name_to_type, generated_prices